keys = [f"user:{i}" for i in range(10_000)]
servers = ["s1", "s2", "s3", "s4"]


def moved(vnodes):
    before, after = Ring(servers, vnodes), Ring(servers + ["s5"], vnodes)
    return sum(before.server_for(k) != after.server_for(k) for k in keys)


def load(vnodes):
