import bisect
import hashlib
import random
from collections import OrderedDict


def h(s):
    return int(hashlib.md5(s.encode()).hexdigest(), 16)


class Ring:
    def __init__(self, nodes, vnodes=100):
        self.points = sorted((h(f"{n}#{i}"), n) for n in nodes for i in range(vnodes))
        self.keys = [p for p, _ in self.points]

    def node_for(self, key):
        return self.points[bisect.bisect(self.keys, h(key)) % len(self.points)][1]


class LRUNode:
    def __init__(self, capacity):
        self.capacity, self.data = capacity, OrderedDict()

    def get(self, key):
        if key not in self.data:
            return None
        self.data.move_to_end(key)
        return self.data[key]

    def set(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)


class DistributedCache:
    def __init__(self, names, capacity):
        self.capacity = capacity
        self.nodes = {name: LRUNode(capacity) for name in names}
        self.ring = Ring(names)

    def add_node(self, name):
        self.nodes[name] = LRUNode(self.capacity)
        self.ring = Ring(list(self.nodes))

    def get(self, key):
        return self.nodes[self.ring.node_for(key)].get(key)

    def set(self, key, value):
        self.nodes[self.ring.node_for(key)].set(key, value)


def hit_rate(cache, requests):
    hits = 0
    for key in requests:
        if cache.get(key) is not None:
            hits += 1
        else:
            cache.set(key, f"value of {key}")    # cache-aside: fill from the database
    return round(hits / len(requests), 3)


random.seed(3)
keys = [f"user:{i}" for i in range(2_000)]
weights = [1 / (i + 1) for i in range(len(keys))]   # a few keys are very popular
traffic = random.choices(keys, weights, k=50_000)

cache = DistributedCache(["n1", "n2", "n3"], capacity=200)
print("warm-up:", hit_rate(cache, traffic[:20_000]))          # warm-up: 0.78
print("steady:", hit_rate(cache, traffic[20_000:30_000]))     # steady: 0.791
print({name: len(node.data) for name, node in cache.nodes.items()})
# {'n1': 200, 'n2': 200, 'n3': 200}

before = {k: cache.ring.node_for(k) for k in keys}
cache.add_node("n4")
print("moved:", sum(before[k] != cache.ring.node_for(k) for k in keys))   # moved: 546
print("just after:", hit_rate(cache, traffic[30_000:32_000]))  # just after: 0.769
print("warm again:", hit_rate(cache, traffic[32_000:]))        # warm again: 0.83

tradeoffs.answer:
Rules only wins when:
• you are starting out and have no labelled fraud to learn from;
• the rule is a hard requirement: sanctions lists, blocked cards, legal limits;
• a new attack appears today: a rule can be written and deployed in an hour, while a model needs new labels and retraining;
• every decision must be explained in one sentence.
But rules are brittle, rack up false positives, and fraudsters learn them quickly.

An ML model only wins when:
• you have plenty of labelled history and patterns too subtle for hand-written rules (combinations of amount, time, device, merchant, velocity);
• you need a better trade-off between catching fraud and annoying customers than rules can give.
But a model alone is slow to react to brand-new attacks, harder to explain, and a single point of failure if the model service goes down.

Both (the usual production answer): rules as guardrails (hard blocks, known-bad lists, emergency fixes for a fresh attack), the model's score for everything nuanced, thresholds that route to allow, verify, review or block, and rules-only as the fallback when the model is unavailable. Analysts' verdicts feed both: new rules now, better models later.
